import{_ as h,o as t,c,ai as i}from"./chunks/framework.ugHd0fqT.js";const p=JSON.parse('{"title":"Chính sách bảo mật","description":"","frontmatter":{"prev":{"text":"Quy trình tài sản cố định","link":"/TT133/quy-trinh/quy-trinh-tai-san-co-dinh"},"next":{"text":"Quản lý dữ liệu kế toán","link":"/TT133/quan-ly-du-lieu-ke-toan"}},"headers":[],"relativePath":"TT133/chinh-sach-bao-mat.md","filePath":"TT133/chinh-sach-bao-mat.md"}'),a={name:"TT133/chinh-sach-bao-mat.md"};function g(o,n,u,r,s,l){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="chinh-sach-bao-mat" tabindex="-1">Chính sách bảo mật <a class="header-anchor" href="#chinh-sach-bao-mat" aria-label="Permalink to “Chính sách bảo mật”">​</a></h1><p>BKIT luôn hiểu rằng Quý khách hàng rất quan tâm đến việc những thông tin cá nhân mà Quý khách đã tin cậy cung cấp cho chúng tôi được bảo mật và sử dụng ra sao. BKIT cam kết rằng những thông tin này sẽ được chúng tôi nỗ lực tối đa để bảo mật.</p><p>BKIT đảm bảo sẽ sử dụng thông tin khách hàng một cách hợp lý, có cân nhắc để không ngừng cải thiện chất lượng dịch vụ, đem lại cho Quý khách hàng những trải nghiệm tốt hơn khi mua hàng và sử dụng sản phẩm, dịch vụ của chúng tôi.</p><h2 id="_1-muc-đich-va-pham-vi-thu-thap-thong-tin" tabindex="-1">1. Mục đích và phạm vi thu thập thông tin <a class="header-anchor" href="#_1-muc-đich-va-pham-vi-thu-thap-thong-tin" aria-label="Permalink to “1. Mục đích và phạm vi thu thập thông tin”">​</a></h2><p>Để đăng ký sử dụng các dịch vụ phần mềm của BKIT, Quý khách hàng phải đăng ký tài khoản và cung cấp một số thông tin như: <strong>Tên doanh nghiệp, mã số thuế, địa chỉ, người liên hệ, số điện thoại, email và một số thông tin khác</strong>.</p><p>Phần thủ tục đăng ký này giúp BKIT xác định thông tin chính xác của Quý khách hàng nhằm cung cấp quyền sử dụng các sản phẩm, dịch vụ phần mềm. Ngoài ra, những thông tin này sẽ giúp BKIT có thể liên hệ để phục vụ Quý khách hàng trong suốt quá trình sử dụng sản phẩm, dịch vụ của BKIT .</p><div class="info custom-block"><p class="custom-block-title">Lưu ý</p><p>Ngoài những thông tin bắt buộc phải cung cấp được đánh dấu <code>*</code>, Quý khách hàng có thể không cần cung cấp các thông tin không bắt buộc khác. Tuy nhiên, những thông tin này sẽ rất hữu ích cho BKIT khi thực hiện các dịch vụ chăm sóc và hỗ trợ sau bán hàng.</p></div><h2 id="_2-ung-dung-tren-cac-thiet-bi-di-đong" tabindex="-1">2. Ứng dụng trên các thiết bị di động <a class="header-anchor" href="#_2-ung-dung-tren-cac-thiet-bi-di-đong" aria-label="Permalink to “2. Ứng dụng trên các thiết bị di động”">​</a></h2><p>Khi tải và sử dụng các ứng dụng trên thiết bị di động. Quý khách hàng cần cung cấp các quyền sau.</p><p><strong>Với ứng dụng BKIT :</strong></p><ul><li>Nhận dạng giọng nói trên thiết bị.</li><li>Lấy vị trí hiện tại của thiết bị.</li><li>Truy cập vào internet từ thiết bị.</li><li>Truy cập vào Danh bạ.</li><li>Sử dụng micro.</li><li>Chụp ảnh, lưu ảnh vào bộ nhớ máy.</li><li>Thông báo.</li></ul><div class="tip custom-block"><p class="custom-block-title">Khuyến nghị</p><p>Quý khách hàng hoàn toàn có thể ngừng cấp các quyền này thông qua việc cài đặt lại trên thiết bị. Tuy nhiên, BKIT khuyến nghị khách hàng nên cung cấp đủ quyền ứng dụng yêu cầu để ứng dụng có thể hoạt động và vận hành đầy đủ các tính năng cần thiết phục vụ Quý khách hàng.</p></div><h2 id="_3-pham-vi-su-dung-thong-tin" tabindex="-1">3. Phạm vi sử dụng thông tin <a class="header-anchor" href="#_3-pham-vi-su-dung-thong-tin" aria-label="Permalink to “3. Phạm vi sử dụng thông tin”">​</a></h2><p>BKIT cam kết sẽ chỉ sử dụng thông tin của Quý khách hàng để:</p><ul><li>Quản lý và cấp quyền sử dụng các sản phẩm, dịch vụ phần mềm mà BKIT cung cấp cho khách hàng.</li><li>Liên lạc, gửi thông báo cho khách hàng khi sản phẩm, dịch vụ có sự cập nhật, thay đổi.</li><li>Gửi thông báo mời khách hàng đăng ký nâng cấp sản phẩm hoặc gia hạn dịch vụ khi khách hàng sắp hết hạn sử dụng dịch vụ.</li><li>Thực hiện các hoạt động chăm sóc, hỗ trợ sau bán hàng.</li><li>Giải quyết các khiếu nại, tranh chấp.</li></ul><div class="warning custom-block"><p class="custom-block-title">Cam kết</p><p>BKIT cam kết <strong>không chia sẻ thông tin khách hàng cho bất kỳ bên thứ 3 nào</strong> ngoại trừ khi có yêu cầu của cơ quan có thẩm quyền của nhà nước.</p></div><h2 id="_4-thoi-gian-luu-tru-thong-tin" tabindex="-1">4. Thời gian lưu trữ thông tin <a class="header-anchor" href="#_4-thoi-gian-luu-tru-thong-tin" aria-label="Permalink to “4. Thời gian lưu trữ thông tin”">​</a></h2><p>Thông tin của Quý khách hàng là dữ liệu đầu vào quan trọng để BKIT cung cấp và quản lý quyền sử dụng các sản phẩm, dịch vụ phần mềm, vì thế thông tin khách hàng sẽ được lưu trữ trong suốt quá trình hoạt động của BKIT.</p><h2 id="_5-đia-chi-cua-đon-vi-thu-thap-thong-tin" tabindex="-1">5. Địa chỉ của đơn vị thu thập thông tin <a class="header-anchor" href="#_5-đia-chi-cua-đon-vi-thu-thap-thong-tin" aria-label="Permalink to “5. Địa chỉ của đơn vị thu thập thông tin”">​</a></h2><p>Địa chỉ của BKIT là: <strong>Công ty TNHH BKIT Việt Nam</strong></p><blockquote><p>Tầng 16, tòa nhà Việt Á, số 9 phố Duy Tân, phường Cầu Giấy, thành phố Hà Nội</p></blockquote><h2 id="_6-cam-ket-bao-mat-thong-tin-ca-nhan-khach-hang" tabindex="-1">6. Cam kết bảo mật thông tin cá nhân khách hàng <a class="header-anchor" href="#_6-cam-ket-bao-mat-thong-tin-ca-nhan-khach-hang" aria-label="Permalink to “6. Cam kết bảo mật thông tin cá nhân khách hàng”">​</a></h2><p>BKIT cam kết luôn nỗ lực sử dụng những biện pháp tốt nhất để bảo mật thông tin của khách hàng nhằm đảm bảo những thông tin này không bị đánh cắp, tiết lộ ngoài ý muốn.</p><p>BKIT cam kết không chia sẻ, bán hoặc cho thuê thông tin của khách hàng với bất kỳ bên thứ ba nào.</p><h2 id="_7-chinh-sach-tich-hop-voi-cac-nen-tang-dich-vu-ben-thu-ba-third-party" tabindex="-1">7. Chính sách tích hợp với các nền tảng, dịch vụ bên thứ ba (Third-Party) <a class="header-anchor" href="#_7-chinh-sach-tich-hop-voi-cac-nen-tang-dich-vu-ben-thu-ba-third-party" aria-label="Permalink to “7. Chính sách tích hợp với các nền tảng, dịch vụ bên thứ ba (Third-Party)”">​</a></h2><p><strong>Google API:</strong> Platform tuân thủ chính sách dữ liệu người dùng của Google (Google API Services User Data Policy), bao gồm yêu cầu về giới hạn sử dụng (Limited Use requirements) khi sử dụng hay chuyển giao thông tin nhận được từ Google API sang ứng dụng khác. cam kết <strong>không chia sẻ thông tin khách hàng cho bất kỳ bên thứ 3 nào</strong> ngoại trừ khi có yêu cầu của cơ quan có thẩm quyền của nhà nước. :::</p><h2 id="_4-thoi-gian-luu-tru-thong-tin-1" tabindex="-1">4. Thời gian lưu trữ thông tin <a class="header-anchor" href="#_4-thoi-gian-luu-tru-thong-tin-1" aria-label="Permalink to “4. Thời gian lưu trữ thông tin”">​</a></h2><p>Thông tin của Quý khách hàng là dữ liệu đầu vào quan trọng để BKIT cung cấp và quản lý quyền sử dụng các sản phẩm, dịch vụ phần mềm, vì thế thông tin khách hàng sẽ được lưu trữ trong suốt quá trình hoạt động của BKIT.</p><h2 id="_5-đia-chi-cua-đon-vi-thu-thap-thong-tin-1" tabindex="-1">5. Địa chỉ của đơn vị thu thập thông tin <a class="header-anchor" href="#_5-đia-chi-cua-đon-vi-thu-thap-thong-tin-1" aria-label="Permalink to “5. Địa chỉ của đơn vị thu thập thông tin”">​</a></h2><p>Địa chỉ của BKIT là: <strong>Công ty TNHH BKIT Việt Nam</strong></p><blockquote><p>Tầng 16, tòa nhà Việt Á, số 9 phố Duy Tân, phường Cầu Giấy, thành phố Hà Nội</p></blockquote><h2 id="_6-cam-ket-bao-mat-thong-tin-ca-nhan-khach-hang-1" tabindex="-1">6. Cam kết bảo mật thông tin cá nhân khách hàng <a class="header-anchor" href="#_6-cam-ket-bao-mat-thong-tin-ca-nhan-khach-hang-1" aria-label="Permalink to “6. Cam kết bảo mật thông tin cá nhân khách hàng”">​</a></h2><p>BKIT cam kết luôn nỗ lực sử dụng những biện pháp tốt nhất để bảo mật thông tin của khách hàng nhằm đảm bảo những thông tin này không bị đánh cắp, tiết lộ ngoài ý muốn.</p><p>BKIT cam kết không chia sẻ, bán hoặc cho thuê thông tin của khách hàng với bất kỳ bên thứ ba nào.</p><h2 id="_7-chinh-sach-tich-hop-voi-cac-nen-tang-dich-vu-ben-thu-ba-third-party-1" tabindex="-1">7. Chính sách tích hợp với các nền tảng, dịch vụ bên thứ ba (Third-Party) <a class="header-anchor" href="#_7-chinh-sach-tich-hop-voi-cac-nen-tang-dich-vu-ben-thu-ba-third-party-1" aria-label="Permalink to “7. Chính sách tích hợp với các nền tảng, dịch vụ bên thứ ba (Third-Party)”">​</a></h2><p><strong>Google API:</strong> Platform tuân thủ chính sách dữ liệu người dùng của Google (Google API Services User Data Policy), bao gồm yêu cầu về giới hạn sử dụng (Limited Use requirements) khi sử dụng hay chuyển giao thông tin nhận được từ Google API sang ứng dụng khác.</p>',36)])])}const d=h(a,[["render",g]]);export{p as __pageData,d as default};
